import{_ as d,l as s,o as a,c,v as o,p as i,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"链接脚本与段","description":"","frontmatter":{"title":"链接脚本与段","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linker-script-sections.md","filePath":"cs/linker-script-sections.md","lastUpdated":1789023840000}'),h={name:"cs/linker-script-sections.md"};function _(m,e,E,A,u,f){const r=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="链接脚本与段" tabindex="-1">链接脚本与段 <a class="header-anchor" href="#链接脚本与段" aria-label="Permalink to &quot;链接脚本与段&quot;">​</a></h1><div class="epigraph"><p>链接脚本描述输出段如何从输入节拼起来、地址多少、对齐多少。嵌入式与内核靠它，而不是靠默认的用户态布局。</p><footer>—— 据 GNU ld 链接脚本文档；ELF 节与段；Levine 整理</footer></div><p>上一课<a href="/cs/linker-symbol-resolution">符号解析</a> 知道哪些 <code>.o</code> 进来。缺口是<strong>放到哪</strong>：<code>.text</code>/<code>.data</code>/<code>.bss</code> 合成哪些 PT_LOAD。链接脚本：<code>SECTIONS { .text : { *(.text*) } }</code>。本课钉节 vs 段，不写 ELF 文件头全文——后课格式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译器吐节（section）；加载器看段（segment）。脚本控制合并、空洞、<code>VMA</code>/<code>LMA</code>（ROM 运行拷到 RAM）。缺口是<strong>布局语言</strong>，不是归档抽取。</p><p>默认脚本服务 SysV 用户态。内核、MCU、引导程序必须自定义：向量表在 0，栈顶符号等。</p><h3 id="节不是段" tabindex="-1">节不是段 <a class="header-anchor" href="#节不是段" aria-label="Permalink to &quot;节不是段&quot;">​</a></h3><p>节给链接与调试；段给 <code>mmap</code>。一个段可含多个节。混淆则「为什么 .text 在文件偏移 X」讲不清。</p><p><span class="marginnote">GNU ld scripts。ELF <code>shdr</code>/<code>phdr</code>。本课嵌入式动机明确。不进限价簿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写脚本：入口 <code>ENTRY</code>、内存区 <code>MEMORY</code>、节输出。丢弃 <code>.comment</code>。提供符号 <code>_end</code>。与 <code>--gc-sections</code>：未引用节可丢，脚本仍要保留入口与向量。</p>',11)),(a(),i(p,null,{default:t(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E8%8A%82%22%5D%20--%3E%20SCR%5B%22%E9%93%BE%E6%8E%A5%E8%84%9A%E6%9C%AC%22%5D%0A%20%20SCR%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E8%8A%82%22%5D%0A%20%20OUT%20--%3E%20PH%5B%22%E7%A8%8B%E5%BA%8F%E6%AE%B5%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与 LTO：优化后节名仍要匹配通配符 <code>*(.text.*)</code>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对齐：缓存行、页。错误脚本使指针差非法或加载失败。不要把脚本当 C 预处理器。</p><p>Overlays：同一 RAM 不同时刻不同映像，脚本支持，点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写动态重定位类型。后课默认：布局由脚本或默认 ABI 布局决定。下一课静态对动态链接。</p><p>也不把脚本当 shell 脚本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链接脚本：输入节 → 输出节/地址。</li><li>节服务链接，段服务加载。</li><li>内核与 MCU 必须自定义布局。</li><li>出处：GNU ld 文档；ELF；Levine。</li></ul>',9))])}const b=d(h,[["render",_]]);export{x as __pageData,b as default};
